import{_ as c,o as a,c as l,ae as i}from"./chunks/framework.EHGTsUvI.js";const p=JSON.parse('{"title":"更新日志","description":"基于仓库近期 git log 整理的 OTools 阶段性更新记录。","frontmatter":{"layout":"doc","title":"更新日志","description":"基于仓库近期 git log 整理的 OTools 阶段性更新记录。"},"headers":[],"relativePath":"guide/changelog.md","filePath":"guide/changelog.md"}'),d={name:"guide/changelog.md"};function o(t,e,s,g,r,h){return a(),l("div",null,[...e[0]||(e[0]=[i('<div class="changelog-hero"><div class="changelog-eyebrow">Recent Shipments · OTools</div><h1>更新日志</h1><p class="changelog-lead"> 基于仓库最近 <code>30</code> 条 <code>git log</code> 整理，按主题提炼近期在 Git、SharkDBM、远程访问、 SSH 信任与桌面能力上的关键更新。 </p><div class="changelog-badges"><span>近 6 天</span><span>30 次提交</span><span>Git / DBM / SSH / 截图</span></div></div><div class="changelog-highlights"><div class="changelog-highlight"><strong>03-20</strong><span>Git 推送稳定性与 SharkDBM 工作区恢复进入密集迭代</span></div><div class="changelog-highlight"><strong>03-19</strong><span>远程访问模式、终端能力与 Git 仓库列表体验同步增强</span></div><div class="changelog-highlight"><strong>03-18</strong><span>跨平台支持、SSH 主机信任机制与编辑器基础能力继续夯实</span></div></div><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>本页依据最近一次 <code>git log -n 30</code> 汇总，保留短提交哈希以便继续追溯源码和提交上下文。</p></div><h2 id="_2026-03-20" tabindex="-1">2026-03-20 <a class="header-anchor" href="#_2026-03-20" aria-label="Permalink to &quot;2026-03-20&quot;">​</a></h2><div class="changelog-grid"><article class="changelog-card"><div class="changelog-card-tag">Git</div><h3>推送链路更稳，弹窗反馈更快</h3><p> 围绕 Git 推送流程连续修复 SSH 认证、推送卡顿、默认远端选择与配置弹窗加载时机，让推送更接近 “点开即用”的体验。 </p><ul><li>调整 SSH 密钥认证顺序，减少推送阶段卡住的概率。</li><li>推送选项对话框改为优先展示，再异步拉取默认配置与远端信息。</li><li>默认优先勾选已跟踪远端，提交后自动推送改为先让用户确认目标。</li></ul><p class="changelog-refs"> 相关提交：<code>5133bc2</code> <code>c669244</code> <code>7bbb4a1</code> <code>a90e1b4</code></p></article><article class="changelog-card"><div class="changelog-card-tag">SharkDBM</div><h3>数据库工作区状态恢复与连接体验持续补强</h3><p> DBM 在这一轮获得了更完整的工作区持久化、连接状态管理、树节点记忆与导入导出能力，同时也持续细化 连接列表和操作反馈。 </p><ul><li>支持工作区状态持久化、树节点展开状态记忆与标签页恢复。</li><li>补充用户管理、连接状态指示器、数据库类型图标与操作防抖。</li><li>围绕连接列表和右侧内容区做了一整轮交互和 UI 优化。</li></ul><p class="changelog-refs"> 相关提交：<code>e9189f9</code> <code>6e825e7</code> <code>6a95422</code> <code>2209493</code></p></article></div><h2 id="_2026-03-19" tabindex="-1">2026-03-19 <a class="header-anchor" href="#_2026-03-19" aria-label="Permalink to &quot;2026-03-19&quot;">​</a></h2><div class="changelog-grid"><article class="changelog-card"><div class="changelog-card-tag">Remote</div><h3>远程访问模式和终端能力继续扩展</h3><p> 远程工作流能力进一步前进，终端与文件传输的使用场景更完整，也更接近日常开发和运维的真实需求。 </p><ul><li>新增远程访问模式，覆盖更多非本地使用场景。</li><li>终端 SFTP 支持上传与下载，补齐高频文件操作链路。</li><li>增加本地终端支持，统一本地与远程工作入口。</li></ul><p class="changelog-refs">相关提交：<code>3c32633</code></p></article><article class="changelog-card"><div class="changelog-card-tag">Git UX</div><h3>仓库列表更顺手，排序和视觉细节同步升级</h3><p> Git 工作区列表从“能用”往“好用”继续推进，强调更直接的组织方式和更清爽的信息层次。 </p><ul><li>支持仓库列表拖动排序，便于按项目优先级整理。</li><li>同步优化列表样式，让高频仓库切换更轻盈。</li></ul><p class="changelog-refs">相关提交：<code>db44329</code> <code>45024e4</code></p></article></div><h2 id="_2026-03-18" tabindex="-1">2026-03-18 <a class="header-anchor" href="#_2026-03-18" aria-label="Permalink to &quot;2026-03-18&quot;">​</a></h2><div class="changelog-grid"><article class="changelog-card"><div class="changelog-card-tag">SSH / 平台</div><h3>跨平台与 SSH 信任机制变得更完整</h3><p> 这一轮重点在基础设施层，既补齐了 Windows/Linux 平台能力，也完善了 SSH 主机密钥信任和错误处理路径。 </p><ul><li>支持 Windows/Linux 平台截图功能。</li><li>封装并落地主机密钥验证与首次指纹信任机制。</li><li>继续优化窗口样式、工具模式配置与编辑器窗口装饰细节。</li></ul><p class="changelog-refs"> 相关提交：<code>9812088</code> <code>b990398</code> <code>d7c2d50</code></p></article><article class="changelog-card"><div class="changelog-card-tag">稳定性</div><h3>编辑器、Git 线程与通用模块继续收口</h3><p> 在功能之外，这一天也包含一批偏“打地基”的整理工作，集中在编辑器统一、线程行为收敛以及 warnings 清理。 </p><ul><li>内置代码编辑器与 SFTP/FTP 编辑链路继续统一。</li><li>Git 推送与拉取相关线程行为被重新梳理。</li><li>数据库、Git、SSH 与工具模块做了一轮稳定性重构。</li></ul><p class="changelog-refs"> 相关提交：<code>fa8e8f4</code> <code>ef04a2d</code> <code>e02e1b2</code></p></article></div><h2 id="_2026-03-17" tabindex="-1">2026-03-17 <a class="header-anchor" href="#_2026-03-17" aria-label="Permalink to &quot;2026-03-17&quot;">​</a></h2><div class="changelog-grid"><article class="changelog-card"><div class="changelog-card-tag">截图</div><h3>截图工作流经历了一轮明显的重做</h3><p> 从蒙层显示到窗口层级控制，再到捕获窗口管理，截图体验在短时间内完成了两轮连续演进。 </p><ul><li>新增截图蒙层功能，提升交互沉浸感。</li><li>优化截图编辑体验，增强窗口层级控制。</li><li>重构截图功能，新增捕获窗口管理与更稳的蒙层逻辑。</li></ul><p class="changelog-refs">相关提交：<code>08a1393</code> <code>89735cc</code></p></article><article class="changelog-card"><div class="changelog-card-tag">生态</div><h3>插件示例与 Git 历史细节同步完善</h3><p> 一边补生态示例，一边打磨 Git 历史与子模块细节，让产品对开发者和日常项目管理都更友好。 </p><ul><li>新增思维导图插件示例页面，扩展示例覆盖面。</li><li>修复 Git 历史时间格式化问题。</li><li>继续优化子模块初始化逻辑。</li></ul><p class="changelog-refs">相关提交：<code>357cace</code></p></article></div><h2 id="_2026-03-15-2026-03-16" tabindex="-1">2026-03-15 ~ 2026-03-16 <a class="header-anchor" href="#_2026-03-15-2026-03-16" aria-label="Permalink to &quot;2026-03-15 ~ 2026-03-16&quot;">​</a></h2><div class="changelog-grid"><article class="changelog-card"><div class="changelog-card-tag">Git / 内容</div><h3>GitHub 集成、认证体验与文档素材能力同步前进</h3><p> 这两天的更新更偏向日常使用效率，既包括 GitHub 集成和 HTTPS 认证，也包括 Markdown 图片上传等内容工作流。 </p><ul><li>新增 GitHub 集成与 HTTPS 凭证管理，优化推送界面。</li><li>支持 Markdown 图片上传，补齐静态资源与存储模块。</li><li>为 Git 提交历史差异查看器加入高度拖拽调节能力。</li></ul><p class="changelog-refs"> 相关提交：<code>0ad8aeb</code> <code>a062ca6</code> <code>ee2b78e</code></p></article><article class="changelog-card"><div class="changelog-card-tag">细节优化</div><h3>IDPhoto 与编辑链路继续微调</h3><p> 除了大型功能外，证件照和编辑器这类高频基础模块也在持续优化，让细节体验更稳定、更顺手。 </p><ul><li>优化 IDPhoto 排版模板展示与默认示例图片加载。</li><li>调整裁剪编辑器缩放逻辑。</li><li>替换 DBM 模块中的 Markdown 编辑器组件。</li></ul><p class="changelog-refs">相关提交：<code>f41c800</code> <code>445d6c0</code></p></article></div><h2 id="原始提交摘录" tabindex="-1">原始提交摘录 <a class="header-anchor" href="#原始提交摘录" aria-label="Permalink to &quot;原始提交摘录&quot;">​</a></h2><details class="changelog-raw"><summary>查看最近 30 条提交</summary><ul><li><code>a90e1b4</code> · 2026-03-20 · fix: 移除 Git 组件推送选项对话框自动提交参数</li><li><code>7bbb4a1</code> · 2026-03-20 · feat: GitPush组件新增默认选中远程仓库逻辑，优化推送选项对话框的远程仓库选择策略</li><li><code>c669244</code> · 2026-03-20 · feat: 优化 Git 推送配置加载逻辑、添加加载状态提示、改进异步处理流程</li><li><code>5133bc2</code> · 2026-03-20 · fix: 调整SSH密钥认证顺序并移除推送超时限制、优化推送流程</li><li><code>e9189f9</code> · 2026-03-20 · feat(dbm): 新增数据库连接超时控制、查询工作台、导入导出功能及UI优化，修复连接管理和代码编辑器问题</li><li><code>6e825e7</code> · 2026-03-20 · feat: 数据库管理器支持工作区状态持久化、树节点展开状态记忆、标签页状态恢复及选中节点保持功能</li><li><code>3554c1f</code> · 2026-03-20 · feat: 更新数据库连接列表组件标题为SharkDBM，重构树节点选择和表/视图/存储过程操作处理逻辑，移除底部边框样式</li><li><code>1289ce9</code> · 2026-03-20 · feat(dbm): 优化数据库连接列表UI，新增连接状态下拉菜单、调整样式布局、改进交互体验</li><li><code>6a95422</code> · 2026-03-20 · feat(dbm): 实现连接状态恢复机制、优化连接列表UI、增强用户管理功能、迁移本地存储结构</li><li><code>f96fbd7</code> · 2026-03-20 · feat(dbm): 新增用户管理、导入导出功能，优化树节点排序与选中逻辑，修复Git推送进度显示</li><li><code>2209493</code> · 2026-03-20 · feat(dbm): 改进数据库连接管理，新增连接状态指示器、数据库类型图标支持、连接操作防抖及侧边栏宽度调整功能</li><li><code>95b84dd</code> · 2026-03-20 · feat: 数据库管理新增视图和存储过程功能、支持表筛选和置顶、优化连接状态管理、完善右键菜单操作、增加收藏命令和SFTP收藏目录功能、修复连接断开状态同步问题、重构标签页管理机制、添加SQL语法高亮支持</li><li><code>3c32633</code> · 2026-03-19 · feat: 支持远程访问模式、终端SFTP支持上传下载、新增本地终端支持、</li><li><code>45024e4</code> · 2026-03-19 · improvement: Git仓库列表样式优化</li><li><code>db44329</code> · 2026-03-19 · feat: Git仓库列表支持拖动排序</li><li><code>fa8e8f4</code> · 2026-03-18 · improvment: Git内置代码编辑器与SFTP/FTP 编辑文件使用通用的CodeMirrorTextEditor及Git推送拉取线程优化</li><li><code>d7c2d50</code> · 2026-03-18 · feat: 优化 macOS 窗口样式适配，调整工具模式窗口配置，修复编辑器窗口装饰问题</li><li><code>b990398</code> · 2026-03-18 · feat: 支持 Windows/Linux 平台截图功能、SSH 主机密钥信任机制、子模块初始化优化及 Git 操作错误处理改进</li><li><code>ef04a2d</code> · 2026-03-18 · refactor: 清理编译warnings，数据库管理、Git操作、SSH连接、工具模块等多项功能重构优化，清理未使用代码并增强稳定性</li><li><code>9812088</code> · 2026-03-18 · feat: 封装通用SSH主机密钥验证与信任功能，支持SSH首次交互存储指纹和错误处理优化。</li><li><code>e02e1b2</code> · 2026-03-18 · feat: AI调用改为通用接口封装、支持证件照的打印功能、新增全局快捷键支持，优化 Git 操作和文件管理功能，修复Windows会打开很多终端问题、优化AI和自动启动执行线程等</li><li><code>89735cc</code> · 2026-03-17 · feat: 重构截图功能，新增捕获窗口管理、优化蒙层显示逻辑、改进窗口层级控制</li><li><code>357cace</code> · 2026-03-17 · feat: 新增思维导图插件示例页面、修复Git历史时间格式化、优化子模块初始化逻辑</li><li><code>08a1393</code> · 2026-03-17 · feat: 新增截图蒙层功能、优化截图编辑体验、增强窗口管理能力</li><li><code>f41c800</code> · 2026-03-16 · feat(idphoto): 调整IDPhoto组件布局样式、优化排版模板选项显示、添加默认示例图片加载功能</li><li><code>a062ca6</code> · 2026-03-16 · feat: 新增 Markdown 图片上传功能，添加静态资源协议处理器和图片存储模块，更新 CSP 配置和依赖项</li><li><code>321faec</code> · 2026-03-15 · refactor: 移除旧版数据迁移逻辑、简化状态管理、优化Git HTTPS认证流程、统一插件入口配置、调整Markdown存储策略</li><li><code>0ad8aeb</code> · 2026-03-15 · feat: 新增 GitHub 集成与 HTTPS 凭证管理、优化推送界面、修复深色主题样式</li><li><code>ee2b78e</code> · 2026-03-15 · feat: 为 Git 提交历史组件添加差异查看器高度调整功能，支持拖拽调节、双击重置及百分比显示</li><li><code>445d6c0</code> · 2026-03-15 · refactor: 调整裁剪编辑器缩放逻辑、替换dbm模块Markdown编辑器组件</li></ul></details>',15)])])}const f=c(d,[["render",o]]);export{p as __pageData,f as default};
